import{c as o,Q as t,j as a,m as s}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Claude Code 社群實踐 — Workspace 改善與執行計劃書","description":"","frontmatter":{"title":"Claude Code 社群實踐 — Workspace 改善與執行計劃書","author":"Opus 4.8 (draft) → Sonnet 4.6 (revision)","date":"2026-06-07T00:00:00.000Z","status":"部分執行（2026-06-07，見 §15 執行狀態）","branch":"feature/claudecode-improvement-plan","sources":["2026-06-07-claude-code-community-practices-report.md (32 篇社群實踐, PR","2026-06-07-claude-code-deep-practices-v2.md (盲點補足 v2, PR","2026-06-07-session-insights.md","2026-06-07-session-insights-v2.md"],"type":"execution-plan"},"headers":[],"relativePath":"research/reports/2026-06-07-claude-code-practices-improvement-execution-plan.md","filePath":"research/reports/2026-06-07-claude-code-practices-improvement-execution-plan.md","lastUpdated":1780842316000}'),r={name:"research/reports/2026-06-07-claude-code-practices-improvement-execution-plan.md"};function n(i,e,l,d,c,h){return t(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="claude-code-社群實踐-—-workspace-改善與執行計劃書" tabindex="-1">Claude Code 社群實踐 — Workspace 改善與執行計劃書 <a class="header-anchor" href="#claude-code-社群實踐-—-workspace-改善與執行計劃書" aria-label="Permalink to &quot;Claude Code 社群實踐 — Workspace 改善與執行計劃書&quot;">​</a></h1><blockquote><p><strong>使用方式</strong>：本計劃書已完整查驗原始來源 + 比對 workspace 現況 + 驗證官方 schema。每項標註「現況」「證據可信度」「建議動作」「驗收條件」「風險」。你逐項核准後執行；破壞性 / schema 未定項目已標 GATE。 <strong>重要校準</strong>：報告原始的 P0/P1/P2 是「社群通用排序」，非「你的 workspace 排序」。本計劃書依<strong>實測現況</strong>重排優先序——多個原 P-tag 在你這裡已是 no-op 或不適用，已降級；真正缺口已升級。 <strong>撰寫流程</strong>：Opus 4.8 起草 → Sonnet 4.6 修訂（符合你指定的雙模型流程）。</p></blockquote><hr><h2 id="_0-執行摘要-—-重排後的真實優先序" tabindex="-1">0. 執行摘要 — 重排後的真實優先序 <a class="header-anchor" href="#_0-執行摘要-—-重排後的真實優先序" aria-label="Permalink to &quot;0. 執行摘要 — 重排後的真實優先序&quot;">​</a></h2><table tabindex="0"><thead><tr><th>重排</th><th>項目</th><th>原 tag</th><th>現況一句話</th><th>動作類型</th></tr></thead><tbody><tr><td><strong>🔴 先驗證</strong></td><td>autoCompactAt 設定</td><td>P0</td><td><strong>schema 無此 key</strong>；真實機制是 env var <code>CLAUDE_AUTOCOMPACT_PCT_OVERRIDE</code>（未文件化+有 bug）→ 預設走人為紀律</td><td>A1 紀律 / A2 試 env var</td></tr><tr><td><strong>🟢 真缺口</strong></td><td>STATUS.md / 跨 session handoff</td><td>P1</td><td>你<strong>沒有</strong> STATUS.md，但已有 <code>schemas/progress.schema.json</code> 未啟用</td><td>採用既有 schema</td></tr><tr><td><strong>🟢 真缺口</strong></td><td>Session length 紀律</td><td>P1</td><td>無「每 N 任務強制 /clear」觸發</td><td>加軟性紀律</td></tr><tr><td><strong>🟢 真缺口</strong></td><td>Skill description 更新</td><td>P2</td><td>27 skills，已有 UserPromptSubmit hook，可增強</td><td>增強既有</td></tr><tr><td><strong>🟡 部分成立</strong></td><td>Centralized kill-switch / 3-tier</td><td>P1</td><td>你是 <code>bypassPermissions</code> + 已有 <code>block-dangerous.sh</code> 分層</td><td>評估 + 補強</td></tr><tr><td><strong>🟡 部分成立</strong></td><td>Hook Narrowness Principle</td><td>P1</td><td><code>block-dangerous.sh</code> 是 376 行 monolith（違反原則）</td><td>評估重構</td></tr><tr><td><strong>⚪ 近 no-op</strong></td><td>Hook exit code 稽核</td><td>P1</td><td><strong>僅 1 個 exit 1</strong>，在 PostCompact/Stop，非阻斷、正確</td><td>確認即可</td></tr><tr><td><strong>⚪ 近 no-op</strong></td><td>MEMORY.md 200 行 cap</td><td>P2</td><td><strong>87/200 行</strong>，遠未觸頂</td><td>加自動 gate（預防）</td></tr><tr><td><strong>🔵 條件式</strong></td><td>.claude/tasks/ JSON persistence</td><td>P2</td><td>已有 progress.schema.json，與 STATUS.md 重疊</td><td>合併到 handoff</td></tr><tr><td><strong>🔵 條件式</strong></td><td>eval harness first</td><td>P2</td><td>已有 eval-designer skill + healthcheck</td><td>流程紀律化</td></tr><tr><td><strong>🔵 條件式</strong></td><td>AST graph navigation</td><td>P2</td><td>workspace 非 code-heavy（研究型）</td><td>不適用，存檔</td></tr></tbody></table><p><strong>一句話結論</strong>：你標的 11 項中，<strong>3 項是真缺口值得做</strong>（STATUS.md handoff、session 紀律、skill description），<strong>2 項近 no-op</strong>（exit code、MEMORY cap——確認比修改重要），<strong>1 項報告建議直接無效</strong>（autoCompactAt schema 不存在），<strong>其餘為條件式 / 不適用</strong>。</p><hr><h2 id="_1-🔴-autocompactat-設定-原-p0-—-報告-key-不存在-真實機制是-env-var-有-bug-警告" tabindex="-1">1. 🔴 autoCompactAt 設定（原 P0）— 報告 key 不存在；真實機制是 env var（有 bug 警告） <a class="header-anchor" href="#_1-🔴-autocompactat-設定-原-p0-—-報告-key-不存在-真實機制是-env-var-有-bug-警告" aria-label="Permalink to &quot;1. 🔴 autoCompactAt 設定（原 P0）— 報告 key 不存在；真實機制是 env var（有 bug 警告）&quot;">​</a></h2><blockquote><p><strong>深度研究後更新（2026-06-07）</strong>：原判「報告建議無效」成立，但補上<strong>真實替代機制</strong>。Claude Code <strong>確實有 built-in auto-compaction</strong>，且<strong>確實有一個可調閾值的機制</strong>——只是不是報告寫的那個 key，而是一個<strong>官方未文件化、且有 reliability bug</strong> 的 env var。以下分三層：機制真相 → 真實 key → 落地建議。</p></blockquote><h3 id="_1-1-機制真相-官方確認" tabindex="-1">1.1 機制真相（官方確認） <a class="header-anchor" href="#_1-1-機制真相-官方確認" aria-label="Permalink to &quot;1.1 機制真相（官方確認）&quot;">​</a></h3><ul><li><strong>Built-in auto-compaction 存在</strong>：context 接近上限時自動摘要舊內容並續跑。</li><li><strong>預設觸發點</strong>：「可用 input tokens − 13,000」的固定 buffer（非乾淨百分比）。200K 模型約落在 <strong>83–95% 使用率</strong>才觸發。來源：<a href="https://github.com/anthropics/claude-code/issues/12004" target="_blank" rel="noreferrer">anthropics/claude-code#12004</a>（原始碼確認 <code>nx1 = 13000</code>）。</li><li><strong>不可由 <code>settings.json</code> 設定</strong>：schema 無 <code>autoCompactAt</code> / <code>tokenBudget</code> / <code>autoCompact</code> / <code>autoCompactThreshold</code> / <code>sessionLimit</code> / <code>warningThreshold</code>。三個要求加此 key 的 feature request（<a href="https://github.com/anthropics/claude-code/issues/28728" target="_blank" rel="noreferrer">#28728</a> / <a href="https://github.com/anthropics/claude-code/issues/41818" target="_blank" rel="noreferrer">#41818</a> / <a href="https://github.com/anthropics/claude-code/issues/25679" target="_blank" rel="noreferrer">#25679</a>）<strong>全部 closed as not planned</strong>。</li></ul><h3 id="_1-2-報告-key-為何無效-已-webfetch-官方-schema-確認" tabindex="-1">1.2 報告 key 為何無效（已 WebFetch 官方 schema 確認） <a class="header-anchor" href="#_1-2-報告-key-為何無效-已-webfetch-官方-schema-確認" aria-label="Permalink to &quot;1.2 報告 key 為何無效（已 WebFetch 官方 schema 確認）&quot;">​</a></h3><ul><li>community-practices [來源宣稱, Branch8]：<code>autoCompactAt: 60%</code>（flat）；deep-practices-v2 [個人宣稱, @zodchiii]：<code>tokenBudget.autoCompactAt: 0.6</code>（nested）。<strong>兩者互相矛盾</strong>。</li><li>官方 schema（<code>https://www.schemastore.org/claude-code-settings.json</code>，即你 settings.json <code>$schema</code> 宣告者）：<code>autoCompactAt</code> / <code>tokenBudget</code> / <code>sessionLimit</code> / <code>dailyLimit</code> / <code>warningThreshold</code> / <code>thinkingTokenLimit</code> → <strong>全部 DOES NOT EXIST</strong>。</li><li><strong>myth 來源</strong>（深研發現）：社群 guide / LLM 生成的 config 片段，很可能<strong>把上述 feature request 提案的 key 名當成已實作的 key 抄出來</strong>（#28728 提案 <code>autoCompactThreshold: 0.85</code>、#41818 提案 <code>compactAtPercent: 66</code>）。無任何證據 <code>autoCompactAt</code> 曾在任何版本真實存在。</li></ul><h3 id="_1-3-真實可調閾值的機制-唯一一條路-但有-bug-警告" tabindex="-1">1.3 真實可調閾值的機制（唯一一條路，但有 bug 警告） <a class="header-anchor" href="#_1-3-真實可調閾值的機制-唯一一條路-但有-bug-警告" aria-label="Permalink to &quot;1.3 真實可調閾值的機制（唯一一條路，但有 bug 警告）&quot;">​</a></h3><ul><li><strong><code>CLAUDE_AUTOCOMPACT_PCT_OVERRIDE</code></strong>（shell env var，非 settings.json）：把 auto-compact 觸發設為百分比（1–100）。 <ul><li>原始碼確認存在（<a href="https://github.com/anthropics/claude-code/issues/12004" target="_blank" rel="noreferrer">#12004</a>）；只能<strong>調低</strong>不能調高（Math.min clamp，<a href="https://github.com/anthropics/claude-code/issues/31806" target="_blank" rel="noreferrer">#31806</a>）→ 設 60 在 clamp 下<strong>有效方向</strong>。</li><li><strong>官方未文件化</strong>（<a href="https://github.com/anthropics/claude-code/issues/20244" target="_blank" rel="noreferrer">#20244</a>）。</li><li><strong>⚠️ reliability bug</strong>：v2.1.79（<a href="https://github.com/anthropics/claude-code/issues/36381" target="_blank" rel="noreferrer">#36381</a>）、v2.1.90（<a href="https://github.com/anthropics/claude-code/issues/42394" target="_blank" rel="noreferrer">#42394</a>）回報<strong>被忽略</strong>；放進 <code>settings.json</code> 的 <code>env</code> block <strong>靜默無效</strong>（<a href="https://github.com/anthropics/claude-code/issues/63186" target="_blank" rel="noreferrer">#63186</a>）→ 必須放 shell rc。</li><li><strong>你的版本 v2.1.168 是否生效：UNVERIFIED</strong>（須實測，見驗收）。</li><li><strong>你的 session 現況</strong>：<code>CLAUDE_AUTOCOMPACT_PCT_OVERRIDE</code> = unset（已查）。</li></ul></li><li><strong><code>claude config set -g autoCompactEnabled false</code></strong>（寫入 <code>~/.claude.json</code>，非 settings.json）：全域關閉 auto-compact。<strong>reliability 有爭議</strong>（<a href="https://github.com/anthropics/claude-code/issues/38483" target="_blank" rel="noreferrer">#38483</a> 回報被忽略，closed not planned）。</li></ul><h3 id="_1-4-建議動作-決策樹" tabindex="-1">1.4 建議動作（決策樹） <a class="header-anchor" href="#_1-4-建議動作-決策樹" aria-label="Permalink to &quot;1.4 建議動作（決策樹）&quot;">​</a></h3><ul><li><strong>A1（推薦預設）— 人為紀律 + 既有 hooks，不依賴 env var</strong>： <ul><li>你 <code>context-management.md</code> 已有「行為信號 &gt; 數字閾值」compact 紀律（70% 一般 / 30–35% 長 agentic）+ <code>/compact &lt;hint&gt;</code> + PreCompact hook（<code>pre-compact.sh</code>）。<strong>這層已運作且不受上述 bug 影響</strong>——是最可靠的「60% 意圖」實現方式（人主動在 60% 下 <code>/compact</code>）。</li><li>零變更、零 schema 風險、零 env-var bug 暴露。</li></ul></li><li><strong>A2（想要自動觸發，願承擔 UNVERIFIED 風險）— 試 env var</strong>：<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 加進 ~/.zshrc（不是 settings.json，後者靜默無效）；重啟 session 才生效</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CLAUDE_AUTOCOMPACT_PCT_OVERRIDE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">60</span></span></code></pre></div><ul><li><strong>必須實測驗證</strong>（見驗收）；若 v2.1.168 仍有 #42394 的 bug 則無效，退回 A1。</li></ul></li><li><strong>A3（成本控制，與閾值無關）— schema-confirmed</strong>： <ul><li><code>model</code>（schema 存在）：選成本較低 model 結構性降成本。</li><li><code>autoMemoryEnabled: true</code>（你<strong>已開</strong>）：offload 記憶到 MEMORY.md，間接減 context 壓力。</li><li><code>cleanupPeriodDays</code>（schema 存在）：控 transcript 保留天數（與 compact 閾值<strong>無關</strong>，別誤用為成本上限）。</li><li>成本監控用 <code>ccusage</code> / <code>/usage</code>，非 config 硬上限。</li></ul></li><li><strong>A4（不做）</strong>：不寫 <code>autoCompactAt</code> 進 settings.json（schema 無效，validator 標紅或靜默忽略）。</li></ul><h3 id="驗收條件" tabindex="-1">驗收條件 <a class="header-anchor" href="#驗收條件" aria-label="Permalink to &quot;驗收條件&quot;">​</a></h3><ul><li>A1：<code>python3 -m json.tool .claude/settings.json</code> 通過，未引入 schema 無效 key。</li><li>A2（若採）：export 後<strong>重啟 session</strong>，跑長對話觀察 compaction 是否在 <strong>&lt;70% context</strong> 觸發（觸發 = 生效；到 83%+ 才觸發 = 仍 bug，退 A1）。<code>echo $CLAUDE_AUTOCOMPACT_PCT_OVERRIDE</code> 應回 <code>60</code>。</li></ul><h3 id="風險" tabindex="-1">風險 <a class="header-anchor" href="#風險" aria-label="Permalink to &quot;風險&quot;">​</a></h3><ul><li><strong>A1 零風險</strong>（純人為紀律 + 既有機制）。</li><li><strong>A2 中風險</strong>：env var UNVERIFIED on v2.1.168，可能靜默無效（假安全感）；故列為「願承擔風險才試」，預設走 A1。</li></ul><h3 id="來源" tabindex="-1">來源 <a class="header-anchor" href="#來源" aria-label="Permalink to &quot;來源&quot;">​</a></h3><p>官方：<a href="https://code.claude.com/docs/en/hooks" target="_blank" rel="noreferrer">Hooks</a> · <a href="https://code.claude.com/docs/en/settings" target="_blank" rel="noreferrer">Settings</a> · <a href="https://www.schemastore.org/claude-code-settings.json" target="_blank" rel="noreferrer">SchemaStore</a>。Issues：#12004（13K buffer）· #20244（env 未文件化）· #31806（只能調低）· #36381 / #42394（被忽略 bug）· #63186（settings.json env block 無效）· #38483（autoCompactEnabled 被忽略）· #28728 / #41818 / #25679（feature request 全 not planned）。</p><hr><h2 id="_2-🟢-status-md-跨-session-handoff-原-p1-—-真缺口-但用既有-schema" tabindex="-1">2. 🟢 STATUS.md / 跨 session handoff（原 P1）— 真缺口，但用既有 schema <a class="header-anchor" href="#_2-🟢-status-md-跨-session-handoff-原-p1-—-真缺口-但用既有-schema" aria-label="Permalink to &quot;2. 🟢 STATUS.md / 跨 session handoff（原 P1）— 真缺口，但用既有 schema&quot;">​</a></h2><h3 id="現況" tabindex="-1">現況 <a class="header-anchor" href="#現況" aria-label="Permalink to &quot;現況&quot;">​</a></h3><ul><li><code>ls STATUS.md</code> → <strong>不存在</strong>。</li><li>但 <code>schemas/progress.schema.json</code> <strong>已存在</strong>（Justin Young 2025 pattern，session-stop.sh 會 auto-update <code>updated_at</code>），且 SessionStart hook 已偵測「無 claude-progress.json」並提示建立。</li><li>→ 這不是「設計新 handoff 格式」，而是「<strong>啟用既有但未使用的 schema</strong>」。</li></ul><h3 id="證據與可信度" tabindex="-1">證據與可信度 <a class="header-anchor" href="#證據與可信度" aria-label="Permalink to &quot;證據與可信度&quot;">​</a></h3><ul><li>community-practices [來源宣稱, Eva Khmelinskaya]：CLAUDE.md 在 90+ 分鐘 session 後被 compact 丟失 → STATUS.md 修復。格式：<code>{task, phase, last_checkpoint, next_action, blockers}</code>（lines 151–174）。</li><li>deep-practices-v2 [失敗案例類型學]：同一「instruction dilution」現象（line 104）。</li><li><strong>比對</strong>：<code>progress.schema.json</code> 已含 <code>next_action</code>（&quot;prevents premature completion&quot;）、<code>sessions</code>、<code>current_step</code>、<code>status</code> — <strong>覆蓋報告建議的 STATUS.md 欄位且更完整</strong>。報告的 STATUS.md 是 progress.schema 的子集。</li></ul><h3 id="建議動作" tabindex="-1">建議動作 <a class="header-anchor" href="#建議動作" aria-label="Permalink to &quot;建議動作&quot;">​</a></h3><ul><li><strong>B1（推薦）</strong>：採用 <code>progress.schema.json</code> 取代另造 STATUS.md。長任務（overnight / 跨 session）開工時建 <code>claude-progress.json</code>（SessionStart hook 已會提示）。</li><li><strong>B2</strong>：在 <code>core.md</code>「長期記憶回路」段加 1 行：「跨 session / overnight 任務開工 → 建 <code>claude-progress.json</code>（schema: <code>schemas/progress.schema.json</code>）」。<strong>注意 auto-load byte 預算</strong>（現 18,726 / cap 19,000，餘 274）——這 1 行約 +120 B，可容；若超則放 <code>refs/</code> 加指針。</li><li><strong>B3（不做）</strong>：不另造 STATUS.md（與 progress.json 重複 = 維護債）。</li></ul><h3 id="驗收條件-1" tabindex="-1">驗收條件 <a class="header-anchor" href="#驗收條件-1" aria-label="Permalink to &quot;驗收條件&quot;">​</a></h3><ul><li><code>python3 -c &quot;import json,jsonschema; ...&quot;</code> 或簡易 <code>python3 -m json.tool claude-progress.json</code> 對一個樣本檔通過。</li><li>session-stop.sh 對該檔的 <code>updated_at</code> auto-update 實測生效（建檔後跑一次 session 結束驗證）。</li></ul><h3 id="風險-1" tabindex="-1">風險 <a class="header-anchor" href="#風險-1" aria-label="Permalink to &quot;風險&quot;">​</a></h3><ul><li><strong>低</strong>。僅新增使用慣例 + ≤1 行 auto-load。byte 預算需先量測。</li></ul><hr><h2 id="_3-🟢-session-length-紀律-原-p1-—-真缺口-加軟性觸發" tabindex="-1">3. 🟢 Session length 紀律（原 P1）— 真缺口，加軟性觸發 <a class="header-anchor" href="#_3-🟢-session-length-紀律-原-p1-—-真缺口-加軟性觸發" aria-label="Permalink to &quot;3. 🟢 Session length 紀律（原 P1）— 真缺口，加軟性觸發&quot;">​</a></h2><h3 id="現況-1" tabindex="-1">現況 <a class="header-anchor" href="#現況-1" aria-label="Permalink to &quot;現況&quot;">​</a></h3><ul><li><code>context-management.md</code> 已有 compact 觸發（行為信號 + 70%/30% 閾值），但<strong>無「每 N 任務 /clear」計數觸發</strong>。</li><li>core.md 有「每重要步驟 checkpoint」，但 checkpoint ≠ session 邊界紀律。</li></ul><h3 id="證據與可信度-1" tabindex="-1">證據與可信度 <a class="header-anchor" href="#證據與可信度-1" aria-label="Permalink to &quot;證據與可信度&quot;">​</a></h3><ul><li>community-practices [來源宣稱, Jamie Cole 30 天回顧]：47 任務 25% 放棄率（12/47）；「每 5 任務 1 regression」；&quot;One task, one session&quot;（lines 329–345）。</li><li>deep-practices-v2 [個人宣稱, Sean Moran ★★★☆☆]：2026 範式轉移「long session &gt; frequent /clear」（lines 26–37）——<strong>與 Jamie Cole 方向相反</strong>。</li><li><strong>矛盾標記</strong>：Jamie Cole 主張短 session / 勤 /clear；Sean Moran 主張 long session 已從「脆弱」變「資產」。兩者皆 [個人宣稱]，無學術背書。<strong>不可同時採信</strong>（core.md 浮現矛盾紀律）。</li><li>「30–60 min session」門檻：兩份報告 researcher 均確認<strong>非 Jamie Cole 建議</strong>，而是 Eva Khmelinskaya 對 overnight agent 的 session cap（context-dependent）。</li></ul><h3 id="建議動作-1" tabindex="-1">建議動作 <a class="header-anchor" href="#建議動作-1" aria-label="Permalink to &quot;建議動作&quot;">​</a></h3><ul><li><strong>C1（推薦，折衷）</strong>：不採二元立場。加<strong>軟性自評觸發</strong>而非硬性 /clear：「連續完成 5 個獨立任務後，主動自評 context drift（一句 checkpoint：是否出現迷失/重複/規則遺忘）→ 決定 compact 或 continue」。對應 Jamie Cole 的數據點，但保留 Sean Moran 的 long-session 彈性。</li><li><strong>C2</strong>：寫入 <code>context-management.md</code>「Compact 觸發」段，作為「行為信號」的具體化（第 5 任務 = 一個主動檢查點）。約 +100 B。</li><li><strong>C3（不做）</strong>：不設「硬性每 5 任務強制 /clear」——與你 long-session 研究工作流衝突，且 Sean Moran 反證。</li></ul><h3 id="驗收條件-2" tabindex="-1">驗收條件 <a class="header-anchor" href="#驗收條件-2" aria-label="Permalink to &quot;驗收條件&quot;">​</a></h3><ul><li>規則寫入後，下次連續任務 session 實測出現第 5 任務自評 checkpoint。</li><li>auto-load byte 量測 ≤ cap。</li></ul><h3 id="風險-2" tabindex="-1">風險 <a class="header-anchor" href="#風險-2" aria-label="Permalink to &quot;風險&quot;">​</a></h3><ul><li><strong>低</strong>。軟性紀律，不改 harness 機制。矛盾已明示（C2 寫入時加 <code>TODO(conflict): chose soft-5-task-check over hard /clear (Jamie Cole) per Sean Moran long-session evidence; revisit at 2026-Q3</code> 在 <code>context-management.md</code> Compact 觸發段）。</li></ul><hr><h2 id="_4-🟢-skill-description-更新-原-p2-—-增強既有" tabindex="-1">4. 🟢 Skill description 更新（原 P2）— 增強既有 <a class="header-anchor" href="#_4-🟢-skill-description-更新-原-p2-—-增強既有" aria-label="Permalink to &quot;4. 🟢 Skill description 更新（原 P2）— 增強既有&quot;">​</a></h2><h3 id="現況-2" tabindex="-1">現況 <a class="header-anchor" href="#現況-2" aria-label="Permalink to &quot;現況&quot;">​</a></h3><ul><li>27 skills，多數已有 <code>Do NOT use for:</code>（抽查 RESOLVER 與本 session 注入的 skill list 確認大部分已遵循該 pattern）。</li><li>已有 UserPromptSubmit hook（<code>user-prompt-submit.sh</code>）注入 skill 提醒。</li></ul><h3 id="證據與可信度-2" tabindex="-1">證據與可信度 <a class="header-anchor" href="#證據與可信度-2" aria-label="Permalink to &quot;證據與可信度&quot;">​</a></h3><ul><li>deep-practices-v2 [個人宣稱, source-7]：自然觸發 ~20% → UserPromptSubmit hook 注入 → ~84%（lines 315–338）。<strong>注意</strong>：researcher 確認「Alex Opalic」此名 <strong>不在 deep-v2 檔內</strong>（source-7 未具名）；community-practices 也<strong>無此 20%/84% 數字</strong>。→ 數字來源單一、未具名、[個人宣稱]。</li><li>community-practices [來源宣稱, AgentStack/Mayur Panchal]：banlist &gt; stylelist；description 要「pushy」；格式 <code>Use when... Do NOT use for: A, B</code>（lines 393–412）。</li></ul><h3 id="建議動作-2" tabindex="-1">建議動作 <a class="header-anchor" href="#建議動作-2" aria-label="Permalink to &quot;建議動作&quot;">​</a></h3><ul><li><strong>D1（推薦）</strong>：<code>grep -L &quot;Do NOT use for\\|Do not use&quot; .claude/skills/*/SKILL.md</code> → 對回傳的 skill 逐一補齊該欄位。低成本、低風險。</li><li><strong>D2（可選）</strong>：你的 UserPromptSubmit hook 已注入提醒，但<strong>未實作 MANDATORY SKILL ACTIVATION 評估邏輯</strong>（source-7 的 84% 來自此）。可評估是否值得——但 84% 數字單一未具名，<strong>先小規模驗證</strong>（觀察現有 hook 的觸發率）再決定是否加邏輯。</li><li><strong>D3（不做）</strong>：不照搬 source-7 的 TS hook（<code>user-prompt-skill-eval.ts</code>）——你已有 bash hook，雙軌會衝突。</li></ul><h3 id="驗收條件-3" tabindex="-1">驗收條件 <a class="header-anchor" href="#驗收條件-3" aria-label="Permalink to &quot;驗收條件&quot;">​</a></h3><ul><li><code>grep -L &quot;Do NOT use for\\|Do not use&quot; .claude/skills/*/SKILL.md</code> 回傳空（或剩餘清單已逐一確認豁免）。</li></ul><h3 id="風險-3" tabindex="-1">風險 <a class="header-anchor" href="#風險-3" aria-label="Permalink to &quot;風險&quot;">​</a></h3><ul><li><strong>低</strong>（D1）。D2 涉 hook 改動 → 走 Hook Narrowness（見 §6）+ fixture 測試。</li></ul><hr><h2 id="_5-🟡-centralized-kill-switch-3-tier-hooks-原-p1-—-部分成立-重要安全" tabindex="-1">5. 🟡 Centralized kill-switch / 3-tier hooks（原 P1）— 部分成立，重要安全 <a class="header-anchor" href="#_5-🟡-centralized-kill-switch-3-tier-hooks-原-p1-—-部分成立-重要安全" aria-label="Permalink to &quot;5. 🟡 Centralized kill-switch / 3-tier hooks（原 P1）— 部分成立，重要安全&quot;">​</a></h2><h3 id="現況-這裡有真實安全暴露" tabindex="-1">現況（這裡有真實安全暴露） <a class="header-anchor" href="#現況-這裡有真實安全暴露" aria-label="Permalink to &quot;現況（這裡有真實安全暴露）&quot;">​</a></h3><ul><li><code>.claude/settings.json</code> → <code>&quot;defaultMode&quot;: &quot;bypassPermissions&quot;</code>。</li><li>已有分層 deny（<code>rm -rf /</code>、<code>curl|bash</code>、<code>chmod 777</code>）+ <code>block-dangerous.sh</code>（3 個 exit 2 阻斷點）+ <code>branch-isolation-guard.sh</code> + <code>protect-sensitive-files.sh</code>。</li><li>→ 有「單層 hooks」雛形，但<strong>無 centralized kill-switch</strong>，且 <code>bypassPermissions</code> 是高暴露姿態。</li></ul><h3 id="證據與可信度-3" tabindex="-1">證據與可信度 <a class="header-anchor" href="#證據與可信度-3" aria-label="Permalink to &quot;證據與可信度&quot;">​</a></h3><ul><li>deep-practices-v2 [安全研究機構, Check Point Research ★★★★★]： <ul><li><strong>CVE-2025-59536 (CVSS 8.7)</strong>：惡意 repo → <code>.claude/settings.json</code> 的 hooks 在 <strong>trust dialog 出現前</strong>執行 → RCE（lines 591–593）。</li><li><strong>CVE-2026-21852 (CVSS 5.3)</strong>：<code>.claude/settings.json</code> 覆寫 <code>ANTHROPIC_BASE_URL</code> → API key 在 trust dialog 前被攔截（lines 594–597）。</li><li>第三項是「50 subcommand 上限 bypass」，<strong>非</strong> researcher A 誤記的「CVE-2025-54794」（已查驗澄清）。</li></ul></li><li>[學術, arXiv 2604.14228 ★★★★★]：CLAUDE.md = user context（~70% 機率遵從），hooks = 100% 確定性；安全規則放 CLAUDE.md 是設計錯誤（lines 58–63）。</li><li><strong>直接關聯你的姿態</strong>：你的 <code>bypassPermissions</code> 正是 CVE-2025-59536 描述的暴露面——clone 惡意 repo 時其 <code>.claude/settings.json</code> hooks 可在你 trust 前執行。</li></ul><h3 id="建議動作-3" tabindex="-1">建議動作 <a class="header-anchor" href="#建議動作-3" aria-label="Permalink to &quot;建議動作&quot;">​</a></h3><ul><li><strong>E1（推薦，先評估）</strong>：稽核你 clone 外部 repo 的習慣——是否曾在未審查 <code>.claude/settings.json</code> 下開 session？若是，<strong>這是 P0 級安全項</strong>（升級）。檢查：你的 workspace 是否只在自己的 trusted repo 開 session（是 → 暴露低）。</li><li><strong>E2</strong>：考慮 <code>bypassPermissions</code> → 至少對「clone 的外部 repo」改用 <code>default</code>/<code>acceptEdits</code> 模式（per-project settings）。你自己的 cc-workspace 可維持 bypass（trusted）。</li><li><strong>E3（kill-switch）</strong>：3-tier 是給「組織管理多開發者」的；你是單人 workspace → centralized remote kill-switch <strong>過度工程</strong>。替代：把安全關鍵規則確認都在 hooks（已大致如此）而非 CLAUDE.md（符合 arXiv 發現）。</li><li><strong>E4</strong>：稽核 <code>.claude/settings.json</code> 的 hooks 是否全指向 repo 內受信任腳本（<code>grep command .claude/settings.json</code> → 全部 <code>$CLAUDE_PROJECT_DIR/.claude/hooks/*</code> = 安全）。</li></ul><h3 id="驗收條件-4" tabindex="-1">驗收條件 <a class="header-anchor" href="#驗收條件-4" aria-label="Permalink to &quot;驗收條件&quot;">​</a></h3><ul><li>列出所有 hook command 來源，確認 0 個指向外部 / 非 repo 腳本。</li><li>決策記錄：bypassPermissions 維持 or 收緊（附理由）。</li></ul><h3 id="風險-4" tabindex="-1">風險 <a class="header-anchor" href="#風險-4" aria-label="Permalink to &quot;風險&quot;">​</a></h3><ul><li><strong>E2 中風險</strong>（改 permission mode 影響日常流暢度）→ 需你決定 trade-off。E4 零風險（只讀稽核）。</li></ul><hr><h2 id="_6-🟡-hook-narrowness-principle-原-p1-—-部分成立-評估重構" tabindex="-1">6. 🟡 Hook Narrowness Principle（原 P1）— 部分成立，評估重構 <a class="header-anchor" href="#_6-🟡-hook-narrowness-principle-原-p1-—-部分成立-評估重構" aria-label="Permalink to &quot;6. 🟡 Hook Narrowness Principle（原 P1）— 部分成立，評估重構&quot;">​</a></h2><h3 id="現況-3" tabindex="-1">現況 <a class="header-anchor" href="#現況-3" aria-label="Permalink to &quot;現況&quot;">​</a></h3><ul><li><code>block-dangerous.sh</code> = <strong>376 行 monolith</strong>（34 個 exit 0 + 3 個 exit 2），單檔處理多規則 → <strong>違反 Narrowness Principle</strong>。</li><li>其他 hooks 多數單一職責（branch-isolation / protect-sensitive / memory-sync 各管一事）。</li></ul><h3 id="證據與可信度-4" tabindex="-1">證據與可信度 <a class="header-anchor" href="#證據與可信度-4" aria-label="Permalink to &quot;證據與可信度&quot;">​</a></h3><ul><li>community-practices [來源宣稱, Jangwook Kim]：一 hook 一規則；anti-pattern = if/elif merge 10 規則，單一 regex error 汙染全部（lines 69–88）。</li><li>deep-practices-v2 [設計原則, hooks-security-gates-narrowness]：① 一 hook 一規則 ↔ 一 fixture pair；② safe/dangerous payload 在 Claude Code 外測試；③ <code>jq</code> 結構化解析 &gt; regex（lines 289–296）。</li></ul><h3 id="建議動作-4" tabindex="-1">建議動作 <a class="header-anchor" href="#建議動作-4" aria-label="Permalink to &quot;建議動作&quot;">​</a></h3><ul><li><strong>F1（推薦，評估而非立即拆）</strong>：<code>block-dangerous.sh</code> 376 行雖違反原則，但<strong>已運作且有 3 層設計</strong>（line 18 註解：allowlist → 不在清單 exit 2）。拆分 = 大改動、有回歸風險。先評估「拆分收益 vs 風險」：單人 workspace、該檔穩定 → <strong>可暫不拆</strong>，但<strong>必須補 fixture 測試</strong>（最高價值動作）。</li><li><strong>F2（推薦，高價值低風險）</strong>：為 <code>block-dangerous.sh</code> 建 fixture pair 測試（safe payload 應 exit 0 / dangerous payload 應 exit 2），放 <code>tests/hooks/</code>。這直接實現 Narrowness 原則 ②，且<strong>不動現有邏輯</strong>。</li><li><strong>F3（可選）</strong>：新增 hook 時遵循「一 hook 一規則」+ <code>jq</code> 解析（原則 ①③），但<strong>不回頭重構</strong> block-dangerous（Rule of proportionality）。</li></ul><h3 id="驗收條件-5" tabindex="-1">驗收條件 <a class="header-anchor" href="#驗收條件-5" aria-label="Permalink to &quot;驗收條件&quot;">​</a></h3><ul><li><code>tests/hooks/test-block-dangerous.sh</code> 存在，涵蓋 ≥3 safe + ≥3 dangerous fixture，全綠。</li><li>測試能在 block 邏輯被改壞時失敗（驗意圖，非驗實作）。</li></ul><h3 id="風險-5" tabindex="-1">風險 <a class="header-anchor" href="#風險-5" aria-label="Permalink to &quot;風險&quot;">​</a></h3><ul><li><strong>F2 低風險</strong>（純加測試）。F1 拆分若做 = 中高風險，故建議暫緩。</li></ul><hr><h2 id="_7-⚪-hook-exit-code-稽核-原-p1-—-近-no-op-確認即可" tabindex="-1">7. ⚪ Hook exit code 稽核（原 P1）— 近 no-op，確認即可 <a class="header-anchor" href="#_7-⚪-hook-exit-code-稽核-原-p1-—-近-no-op-確認即可" aria-label="Permalink to &quot;7. ⚪ Hook exit code 稽核（原 P1）— 近 no-op，確認即可&quot;">​</a></h2><h3 id="現況-已實測" tabindex="-1">現況（已實測） <a class="header-anchor" href="#現況-已實測" aria-label="Permalink to &quot;現況（已實測）&quot;">​</a></h3><ul><li><code>grep -rn &quot;exit 1&quot; .claude/hooks/</code> → <strong>僅 1 個</strong>：<code>memory-sync.sh:44</code>。</li><li>該 <code>exit 1</code> 在 <strong>PostCompact / Stop</strong> 事件（remote URL mismatch → abort sync）。</li><li>exit code 直方圖：所有阻斷意圖都正確用 <code>exit 2</code>（block-dangerous ×3、pre-commit-review ×3、protect-sensitive ×2、branch-isolation ×1、session-init ×8、pre-compact ×2、sdd-cache-pre ×1）。</li></ul><h3 id="證據與可信度-5" tabindex="-1">證據與可信度 <a class="header-anchor" href="#證據與可信度-5" aria-label="Permalink to &quot;證據與可信度&quot;">​</a></h3><ul><li>兩份報告 [官方語義]：exit 1 = 非阻斷（Unix convention）；exit 2 = Claude Code 阻斷信號。</li><li><strong>比對你的 hooks</strong>：唯一的 exit 1 在 PostCompact/Stop——這兩個事件 exit 2 的語義是「阻止 stop / 無阻斷效果」，故此處 <code>exit 1</code>（中止 sync 流程、非阻斷 harness）<strong>語義正確、非誤用</strong>。</li></ul><h3 id="建議動作-5" tabindex="-1">建議動作 <a class="header-anchor" href="#建議動作-5" aria-label="Permalink to &quot;建議動作&quot;">​</a></h3><ul><li><strong>G1（推薦）</strong>：確認 <code>memory-sync.sh:44</code> 的 <code>exit 1</code> 為「有意的非阻斷中止」（已確認：remote mismatch 時放棄 sync，不該阻斷 session）→ <strong>保持不變</strong>，加 1 行註解標明「# exit 1: non-blocking abort (PostCompact/Stop event, intentional)」避免未來誤改。</li><li><strong>G2（不做）</strong>：報告建議的「全面 exit 1 → exit 2 稽核」在你這裡已完成且通過——<strong>不需要批次修改</strong>。</li></ul><h3 id="驗收條件-6" tabindex="-1">驗收條件 <a class="header-anchor" href="#驗收條件-6" aria-label="Permalink to &quot;驗收條件&quot;">​</a></h3><ul><li><code>memory-sync.sh:44</code> 加註解（1 行）；其餘 hooks 無變更。</li></ul><h3 id="風險-6" tabindex="-1">風險 <a class="header-anchor" href="#風險-6" aria-label="Permalink to &quot;風險&quot;">​</a></h3><ul><li><strong>零</strong>（1 行註解）。</li></ul><hr><h2 id="_8-⚪-memory-md-200-行-cap-原-p2-—-近-no-op-加預防-gate" tabindex="-1">8. ⚪ MEMORY.md 200 行 cap（原 P2）— 近 no-op，加預防 gate <a class="header-anchor" href="#_8-⚪-memory-md-200-行-cap-原-p2-—-近-no-op-加預防-gate" aria-label="Permalink to &quot;8. ⚪ MEMORY.md 200 行 cap（原 P2）— 近 no-op，加預防 gate&quot;">​</a></h2><h3 id="現況-已實測-1" tabindex="-1">現況（已實測） <a class="header-anchor" href="#現況-已實測-1" aria-label="Permalink to &quot;現況（已實測）&quot;">​</a></h3><ul><li><code>wc -l MEMORY.md</code> → <strong>87 行 / 200</strong>（43% 使用率，遠未觸頂）。</li><li>已有 <code>memory-compactor</code> skill + agent（&gt;200 行時委派）。</li></ul><h3 id="證據與可信度-6" tabindex="-1">證據與可信度 <a class="header-anchor" href="#證據與可信度-6" aria-label="Permalink to &quot;證據與可信度&quot;">​</a></h3><ul><li>community-practices [來源宣稱, Ian Paterson]：always-loaded ≤200 行；「501 行導致 60% lessons 不可見」（lines 241–248）。</li><li>deep-practices-v2 [官方引述, Boris Cherny ★★★★☆]：CLAUDE.md 最佳 &lt;200 行 / &lt;5,000 tokens（lines 283–286）。<strong>注意</strong>：此 cap 報告中指 <strong>CLAUDE.md</strong>，非 MEMORY.md；MEMORY.md 的 200 行 cap 來自 Ian Paterson 的 always-loaded layer。</li></ul><h3 id="建議動作-6" tabindex="-1">建議動作 <a class="header-anchor" href="#建議動作-6" aria-label="Permalink to &quot;建議動作&quot;">​</a></h3><ul><li><strong>H1（推薦）</strong>：你的 MEMORY.md cap 200 已寫進 <code>core.md</code>（「總行 &gt;200 → 委派 memory-compactor」），機制<strong>已存在</strong>。87 行 → 無需動作。</li><li><strong>H2（可選預防）</strong>：在 session-stop.sh 加軟性提醒：<code>wc -l MEMORY.md</code> &gt;180 行時輸出警示（提前於 200 觸發）。約 +5 行 bash。但<strong>現狀 87 行，優先序低</strong>。</li><li><strong>H3（澄清）</strong>：你的 CLAUDE.md ≤200 行規則（不同於 MEMORY.md）已守（現況見 <code>wc -l CLAUDE.md</code>；core.md §Framework Integrity 管理）。</li></ul><h3 id="驗收條件-7" tabindex="-1">驗收條件 <a class="header-anchor" href="#驗收條件-7" aria-label="Permalink to &quot;驗收條件&quot;">​</a></h3><ul><li>無需立即動作。若做 H2：人為觸發 &gt;180 行測試輸出警示。</li></ul><h3 id="風險-7" tabindex="-1">風險 <a class="header-anchor" href="#風險-7" aria-label="Permalink to &quot;風險&quot;">​</a></h3><ul><li><strong>零 ~ 極低</strong>。</li></ul><hr><h2 id="_9-🔵-claude-tasks-json-persistence-原-p2-—-合併到-§2-handoff" tabindex="-1">9. 🔵 .claude/tasks/ JSON persistence（原 P2）— 合併到 §2 handoff <a class="header-anchor" href="#_9-🔵-claude-tasks-json-persistence-原-p2-—-合併到-§2-handoff" aria-label="Permalink to &quot;9. 🔵 .claude/tasks/ JSON persistence（原 P2）— 合併到 §2 handoff&quot;">​</a></h2><h3 id="現況-4" tabindex="-1">現況 <a class="header-anchor" href="#現況-4" aria-label="Permalink to &quot;現況&quot;">​</a></h3><ul><li><code>ls .claude/tasks/</code> → 不存在。但 <code>schemas/progress.schema.json</code> 已覆蓋「跨 session 任務持久化」需求。</li></ul><h3 id="證據與可信度-7" tabindex="-1">證據與可信度 <a class="header-anchor" href="#證據與可信度-7" aria-label="Permalink to &quot;證據與可信度&quot;">​</a></h3><ul><li>community-practices [來源宣稱, Alex Opalic]：<code>{task_id, status, spec, last_commit, blockers}</code>（line 339）。</li><li>deep-practices-v2 [來源宣稱, Ralph Loop]：<code>tasks.json</code> 作持久記憶；<strong>注意</strong>：researcher 確認 deep-v2 <strong>未指定 <code>.claude/tasks/</code> 具體路徑</strong>，用泛稱 <code>tasks.json</code>。</li></ul><h3 id="建議動作-7" tabindex="-1">建議動作 <a class="header-anchor" href="#建議動作-7" aria-label="Permalink to &quot;建議動作&quot;">​</a></h3><ul><li><strong>I1（推薦）</strong>：<strong>不另建 <code>.claude/tasks/</code></strong>。與 §2 的 <code>claude-progress.json</code> 合併——後者 schema 已含 <code>steps[]</code>（含 id/title/status/notes）、<code>current_step</code>、<code>next_action</code>，<strong>完全覆蓋</strong> Alex Opalic 的 <code>{task_id, status, spec, last_commit, blockers}</code>。</li><li><strong>I2（不做）</strong>：避免 STATUS.md + .claude/tasks/ + claude-progress.json 三套並存（維護債 + 規則矛盾）。</li></ul><h3 id="驗收條件-8" tabindex="-1">驗收條件 <a class="header-anchor" href="#驗收條件-8" aria-label="Permalink to &quot;驗收條件&quot;">​</a></h3><ul><li>同 §2（採用 progress.schema.json 即同時滿足本項）。</li></ul><h3 id="風險-8" tabindex="-1">風險 <a class="header-anchor" href="#風險-8" aria-label="Permalink to &quot;風險&quot;">​</a></h3><ul><li><strong>零</strong>（合併，不新增）。</li></ul><hr><h2 id="_10-🔵-eval-harness-first-原-p2-—-流程紀律化" tabindex="-1">10. 🔵 eval harness first（原 P2）— 流程紀律化 <a class="header-anchor" href="#_10-🔵-eval-harness-first-原-p2-—-流程紀律化" aria-label="Permalink to &quot;10. 🔵 eval harness first（原 P2）— 流程紀律化&quot;">​</a></h2><h3 id="現況-5" tabindex="-1">現況 <a class="header-anchor" href="#現況-5" aria-label="Permalink to &quot;現況&quot;">​</a></h3><ul><li>已有 <code>eval-designer</code> skill（4 條件：auto-calculable / hard-to-hack / target-relevant / sensitive）+ <code>scripts/healthcheck.sh</code> + core.md TEST 階段「測試驗意圖」紀律。</li><li>→ 「eval-first」精神<strong>已存在於 harness 哲學</strong>，但無「先建 eval 再寫 feature」的強制流程。</li></ul><h3 id="證據與可信度-8" tabindex="-1">證據與可信度 <a class="header-anchor" href="#證據與可信度-8" aria-label="Permalink to &quot;證據與可信度&quot;">​</a></h3><ul><li>community-practices [來源宣稱, RAG 11 天案例]：Day 1-2 先建 50 fixtures；87% pass / 20% rejection；read-only reviewer 防 auto-accept（lines 465–487）。</li><li>deep-practices-v2 [業界領袖, Addy Osmani]：@reviewer 只讀 teammate（lines 207–212）；[學術, source-8（未具名）]：LLM 生成 AGENTS.md 無益、降 ~3% 成功率、增 20% 成本（lines 227–229）。</li></ul><h3 id="建議動作-8" tabindex="-1">建議動作 <a class="header-anchor" href="#建議動作-8" aria-label="Permalink to &quot;建議動作&quot;">​</a></h3><ul><li><strong>J1（推薦）</strong>：你的 workspace 是<strong>研究型</strong>（非 feature-heavy code repo），「eval-first 50 fixtures」對研究報告不直接適用。對<strong>有實作的任務</strong>（hooks/scripts）→ 套用既有 <code>eval-designer</code> + §6 的 fixture 測試已覆蓋。</li><li><strong>J2（採納 read-only reviewer 精神）</strong>：你已有 <code>/deep-review</code>、<code>review-hub</code>、<code>code-reviewer</code> agent（Read/Grep/Glob only = 天然 read-only）→ <strong>已符合</strong>。確認 reviewer agent 無 write 工具即可。</li><li><strong>J3（採納 AGENTS.md 警示）</strong>：core.md 已有「只寫無法從 repo 推導的行為契約」——與「LLM 生成 AGENTS.md 無益」一致。無需動作。</li></ul><h3 id="驗收條件-9" tabindex="-1">驗收條件 <a class="header-anchor" href="#驗收條件-9" aria-label="Permalink to &quot;驗收條件&quot;">​</a></h3><ul><li>確認 <code>code-reviewer</code> / <code>review-hub</code> agent 工具集無 Edit/Write（grep agent 定義）。</li></ul><h3 id="風險-9" tabindex="-1">風險 <a class="header-anchor" href="#風險-9" aria-label="Permalink to &quot;風險&quot;">​</a></h3><ul><li><strong>零</strong>（多為確認既有）。</li></ul><hr><h2 id="_11-🔵-ast-graph-navigation-原-p2-—-不適用-存檔" tabindex="-1">11. 🔵 AST graph navigation（原 P2）— 不適用，存檔 <a class="header-anchor" href="#_11-🔵-ast-graph-navigation-原-p2-—-不適用-存檔" aria-label="Permalink to &quot;11. 🔵 AST graph navigation（原 P2）— 不適用，存檔&quot;">​</a></h2><h3 id="現況-6" tabindex="-1">現況 <a class="header-anchor" href="#現況-6" aria-label="Permalink to &quot;現況&quot;">​</a></h3><ul><li>workspace 是研究 / harness 配置型，<strong>非 &gt;50K loc 的 code-heavy repo</strong>。</li></ul><h3 id="證據與可信度-9" tabindex="-1">證據與可信度 <a class="header-anchor" href="#證據與可信度-9" aria-label="Permalink to &quot;證據與可信度&quot;">​</a></h3><ul><li>兩份報告 [來源宣稱, Graphify / mcplens]：&gt;50K loc → RAG MCP（70-85% token 減）/ AST graph（宣稱 71x）。deep-v2 researcher 確認<strong>未給明確 loc 門檻</strong>；community 給 &gt;50K loc。</li><li>數字 [個人宣稱]，無學術背書，且「71x」是 navigation overhead 對比非總 token。</li></ul><h3 id="建議動作-9" tabindex="-1">建議動作 <a class="header-anchor" href="#建議動作-9" aria-label="Permalink to &quot;建議動作&quot;">​</a></h3><ul><li><strong>K1（不做，存檔）</strong>：你的 codebase 規模未達 RAG/AST 收益點。<strong>列入未來研究</strong>：若 workspace 演化成大型 code repo（或你接手大型專案），再評估。</li><li><strong>K2（研究延伸）</strong>：可做的是「對你常 grep 的大檔（如 block-dangerous.sh 376 行、session-init.sh）建索引」——但收益小，優先序最低。</li></ul><h3 id="驗收條件-10" tabindex="-1">驗收條件 <a class="header-anchor" href="#驗收條件-10" aria-label="Permalink to &quot;驗收條件&quot;">​</a></h3><ul><li>N/A（決策為「暫不採用」）。</li></ul><hr><h2 id="_12-額外發現-報告外-本次查驗浮現" tabindex="-1">12. 額外發現（報告外，本次查驗浮現） <a class="header-anchor" href="#_12-額外發現-報告外-本次查驗浮現" aria-label="Permalink to &quot;12. 額外發現（報告外，本次查驗浮現）&quot;">​</a></h2><ol><li><strong>🔴 bypassPermissions × CVE-2025-59536 直接命中</strong>（見 §5）：你的 default <code>bypassPermissions</code> 正是 Check Point 揭露的暴露面。若你會 clone 外部 repo，這應<strong>升級為 P0 安全評估</strong>。</li><li><strong>本地 main 落後 origin/main 2 commits</strong>：本 session 來源檔（PR #492/#493）在 origin 但不在本地 working tree（已從 origin 讀取）。建議任務結束後 <code>git pull</code> 同步本地 main。</li><li><strong>schema 落差風險普遍化</strong>：autoCompactAt 不存在揭示一個系統性風險——<strong>社群 blog 的 config 建議常引用非官方 / 已棄用 / 版本特定的 key</strong>。建議：未來採納任何 <code>settings.json</code> 建議前，一律先對 <code>https://www.schemastore.org/claude-code-settings.json</code> 驗 key 存在性。可寫成 <code>harness-meta</code> skill 的一個 check。</li><li><strong>report 內部數字矛盾未被原報告標記</strong>：Jamie Cole（短 session）vs Sean Moran（long session）方向相反但同列「最佳實踐」；兩 researcher 對 Branch8 同一數字給不同可信度標（[來源宣稱] vs [企業自述]/[個人宣稱]）。→ 採信前需 source 分級，已在各節標註。</li></ol><hr><h2 id="_13-建議執行順序-你核准後" tabindex="-1">13. 建議執行順序（你核准後） <a class="header-anchor" href="#_13-建議執行順序-你核准後" aria-label="Permalink to &quot;13. 建議執行順序（你核准後）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>批次</th><th>項目</th><th>預估</th><th>風險</th><th>阻斷?</th></tr></thead><tbody><tr><td><strong>批次 0（先驗證）</strong></td><td>§1-A1 採人為紀律（零變更）或 §1-A2 試 <code>CLAUDE_AUTOCOMPACT_PCT_OVERRIDE=60</code>（須重啟+實測）；§5-E4 hook 來源稽核；§12.1 bypassPermissions 暴露評估</td><td>30 min</td><td>零（A1）/ 中（A2 UNVERIFIED）</td><td>A2 須實測通過才採</td></tr><tr><td><strong>批次 1（真缺口，低風險）</strong></td><td>§2 採用 progress.schema；§3 session 紀律 1 行；§4-D1 skill description 補齊；§7 exit 1 註解</td><td>1-2 hr</td><td>低</td><td>auto-load byte 量測 GATE</td></tr><tr><td><strong>批次 2（測試強化）</strong></td><td>§6-F2 block-dangerous fixture 測試；§10-J2 確認 reviewer read-only</td><td>2-3 hr</td><td>低</td><td>—</td></tr><tr><td><strong>批次 3（評估後決定）</strong></td><td>§5-E2 permission mode 收緊（需你決策）；§8-H2 MEMORY 預防警示</td><td>視決策</td><td>中</td><td>你的 trade-off 決定</td></tr><tr><td><strong>不做 / 存檔</strong></td><td>§1 報告原 P0 案、§9 .claude/tasks、§11 AST、§5-E3 kill-switch、§6-F1 拆分</td><td>—</td><td>—</td><td>—</td></tr></tbody></table><p><strong>auto-load byte GATE</strong>：批次 1 涉 §2/§3 寫入 auto-load（現 18,726 / cap 19,000，餘 274 B）。執行前 <code>wc -c CLAUDE.md .claude/rules/*.md</code> 量測；若 §2+§3 合計 &gt;274 B → 下沉到 <code>refs/</code> + auto-load 只留指針（符合 core.md §Framework Integrity「不為塞 byte 反推湊」）。</p><hr><h2 id="_14-驗收總表-healthcheck-友善" tabindex="-1">14. 驗收總表（healthcheck 友善） <a class="header-anchor" href="#_14-驗收總表-healthcheck-友善" aria-label="Permalink to &quot;14. 驗收總表（healthcheck 友善）&quot;">​</a></h2><p>每批次完成後跑 <code>bash scripts/healthcheck.sh</code>，且：</p><ul><li>[ ] §1：<code>python3 -m json.tool .claude/settings.json</code> 通過，未引入 schema-invalid key</li><li>[ ] §2：<code>claude-progress.json</code> 樣本通過 schema 驗證</li><li>[ ] §3：auto-load byte ≤ 19,000（<code>wc -c</code>）</li><li>[ ] §4：<code>grep -L &quot;Do NOT use for&quot; .claude/skills/*/SKILL.md</code> 已逐一確認</li><li>[ ] §5：hook command 來源 100% 指向 repo 內腳本</li><li>[ ] §6：<code>tests/hooks/test-block-dangerous.sh</code> 全綠且能驗意圖</li><li>[ ] §7：<code>memory-sync.sh:44</code> 加註解</li><li>[ ] §10：reviewer agent 工具集無 Edit/Write</li></ul><hr><h2 id="_15-執行狀態-2026-06-07-使用者核准後" tabindex="-1">15. 執行狀態（2026-06-07，使用者核准後） <a class="header-anchor" href="#_15-執行狀態-2026-06-07-使用者核准後" aria-label="Permalink to &quot;15. 執行狀態（2026-06-07，使用者核准後）&quot;">​</a></h2><p>使用者經 AskUserQuestion 拍板：§1=A1 人為紀律｜§5=只稽核不改 mode｜批次 1 採 §2/§4/§7｜其餘採 §6/§10/§12.3/§8｜§3 跳過。<strong>執行時「先讀後動」發現多項已滿足或與既有決策衝突</strong>，誠實記錄如下。</p><h3 id="✅-已執行-commit-本-branch" tabindex="-1">✅ 已執行（commit 本 branch） <a class="header-anchor" href="#✅-已執行-commit-本-branch" aria-label="Permalink to &quot;✅ 已執行（commit 本 branch）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>動作</th><th>驗證</th></tr></thead><tbody><tr><td><strong>§6</strong></td><td><code>tests/hooks/test-block-dangerous.sh</code>（safe→exit0 / dangerous→exit2）</td><td><strong>13/13 pass + mutation test 確認能 fail loud</strong>（中和 block → <code>rm -rf /etc</code> 漏放，測試會抓到）</td></tr><tr><td><strong>§12.3</strong></td><td><code>harness-meta/scripts/schema-verify.sh</code> + SKILL.md Diagnose 步驟加指針</td><td>真 settings PASS(8 key)；注入 <code>autoCompactAt</code>→FAIL。<strong>副發現</strong>：<code>advisorModel</code> 也不在 schemastore（schema 落後），已加 <code>known_real</code> 豁免</td></tr></tbody></table><h3 id="⚪-已滿足-無需動作-執行時-grep-確認" tabindex="-1">⚪ 已滿足，無需動作（執行時 grep 確認） <a class="header-anchor" href="#⚪-已滿足-無需動作-執行時-grep-確認" aria-label="Permalink to &quot;⚪ 已滿足，無需動作（執行時 grep 確認）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>現況</th></tr></thead><tbody><tr><td><strong>§4 skill description</strong></td><td><code>grep -L &quot;Do NOT use for&quot;</code> → <strong>空</strong>。27 skills 全部已有，<strong>無一缺漏</strong> → 無需補齊</td></tr><tr><td><strong>§5-E4 hook 來源稽核</strong></td><td>所有 hook command → <strong>0 個外部來源</strong>，全指向 <code>$CLAUDE_PROJECT_DIR/.claude/hooks/</code> → 安全</td></tr><tr><td><strong>§10 reviewer read-only</strong></td><td><code>reviewer</code> / <code>quick-code-reviewer</code> / <code>security-reviewer</code> 工具集 = <strong><code>Read, Grep, Glob</code></strong>（無 Edit/Write）→ 已天然 read-only</td></tr></tbody></table><h3 id="衝突項-→-已交使用者裁決-2026-06-07-不-silent-fork" tabindex="-1">衝突項 → 已交使用者裁決（2026-06-07，不 silent fork） <a class="header-anchor" href="#衝突項-→-已交使用者裁決-2026-06-07-不-silent-fork" aria-label="Permalink to &quot;衝突項 → 已交使用者裁決（2026-06-07，不 silent fork）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>項目</th><th>衝突</th><th>使用者裁決</th></tr></thead><tbody><tr><td><strong>§8 MEMORY &gt;180 行警示</strong></td><td><strong>直接違反 ADR 2026-05-31</strong>（<code>docs/reference/auto-memory-hybrid.md</code>）：該 ADR <strong>刻意移除</strong> session-stop.sh L300-311 的 MEMORY 大小監控（repo MEMORY.md 已凍結為歷史 log；真實 auto-memory 為 machine-local + 官方優雅降級）。</td><td><strong>DROP</strong> ✅——遵守 ADR，不加警示。當前狀態即正確，無需動作。</td></tr><tr><td><strong>§2 core.md 加指針（B2）</strong></td><td>同 ADR <strong>延後項 #1</strong>：core.md 長期記憶回路段須走 <code>autoload-evolution</code>（≤1 規則/cycle + eval gate），<strong>非 freehand 改 auto-load</strong>，且該段標記待重構對齊兩層模型。基礎設施 <code>session-stop.sh:184-224</code> auto-update + <code>session-init.sh:404-445</code> 讀取<strong>已完整接線</strong> ✓</td><td><strong>走 autoload-evolution 正規加</strong> → 不在本 PR；另起 <code>/autoload-evolution</code> 閉環（≤1 規則/cycle + eval 回歸 gate）把指針正規加進 core.md。<strong>列為後續待辦</strong>。</td></tr></tbody></table><h3 id="§7-使用者核准-→-未執行-狀態明示-不-silent-drop" tabindex="-1">§7（使用者核准）→ 未執行，狀態明示（不 silent drop） <a class="header-anchor" href="#§7-使用者核准-→-未執行-狀態明示-不-silent-drop" aria-label="Permalink to &quot;§7（使用者核准）→ 未執行，狀態明示（不 silent drop）&quot;">​</a></h3><ul><li><strong>§7 exit 1 註解 = NOT DONE</strong>。使用者批次 1 核准了「§7 exit 1 註解」，但執行時「先讀後動」發現：<code>memory-sync.sh</code> 已是 no-op（line 17 <code>exit 0</code>，ADR 2026-05-31 停用自動 commit），故 :44 的 <code>exit 1</code> 是 <strong>dead code（永不執行）</strong>。原計劃「加註解標非阻斷」語義不精確（會誤導為「會執行」）。</li><li><strong>決定</strong>：<strong>不加註解</strong>——對永不執行的死碼加「防誤改」註解價值近零；正確處置是隨 §2 走 autoload-evolution 重構記憶層時一併清理 memory-sync 死碼。<strong>已在收尾向使用者明示此項未做 + 理由</strong>（非靜默跳過）。</li></ul><h3 id="已修正-self-correction-advisor-攔下" tabindex="-1">已修正（self-correction，advisor 攔下） <a class="header-anchor" href="#已修正-self-correction-advisor-攔下" aria-label="Permalink to &quot;已修正（self-correction，advisor 攔下）&quot;">​</a></h3><ul><li><strong><code>schema-verify.sh</code> 的 <code>advisorModel</code> 豁免註解</strong>：原寫 <code>實證</code> 但<strong>從未驗證 harness 實讀此 key</strong>（advisor 工具可用 ≠ 此 key 被讀）→ 已改標 <code>假設未驗證</code>（守 unverified_success 閘門，不掛假 verified-label）。</li><li><strong>§3</strong> 使用者跳過（long-session 偏好），存檔。</li></ul><p><em>草稿 by Opus 4.8 | 修訂 by Sonnet 4.6 | 執行 by Opus 4.8 | 2026-06-07</em></p>`,166)])])}const m=o(r,[["render",n]]);export{u as __pageData,m as default};
